package com.gymmind.membership.api; import com.gymmind.membership.application.*; import com.gymmind.shared.api.ApiResponse; import com.gymmind.shared.security.CurrentActorProvider; import io.swagger.v3.oas.annotations.security.SecurityRequirement; import jakarta.validation.Valid; import jakarta.validation.constraints.NotBlank; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import java.math.BigDecimal; @RestController @RequestMapping("/api/v1/orders") @SecurityRequirement(name="bearerAuth") public class OrderController{private final DefaultOrderService service;private final CurrentActorProvider actors;public OrderController(DefaultOrderService s,CurrentActorProvider a){service=s;actors=a;}@PostMapping @ResponseStatus(HttpStatus.CREATED)public ApiResponse<OrderView>create(@Valid@RequestBody CreateRequest r){return ApiResponse.success(service.create(actors.requireCurrent(),new CreateOrderCommand(null,r.memberId(),r.total(),r.currency())));}public record CreateRequest(Long memberId,BigDecimal total,@NotBlank String currency){}}
